import { useState } from "react";
import MenuTab from "./MenuTab";
import InventoryTab from "./InventoryTab";
import OrdersTab from "./OrdersTab";
import ReportsTab from "./ReportsTab";

export default function AdminPanel() {
  const [tab, setTab] = useState("menu");

  return (
    <section className="card">
      <div className="tabs">
        <button className={`tab-btn ${tab==="menu"?"active":""}`} onClick={()=>setTab("menu")}>Menu</button>
        <button className={`tab-btn ${tab==="inventory"?"active":""}`} onClick={()=>setTab("inventory")}>Inventory</button>
        <button className={`tab-btn ${tab==="orders"?"active":""}`} onClick={()=>setTab("orders")}>Orders</button>
        <button className={`tab-btn ${tab==="reports"?"active":""}`} onClick={()=>setTab("reports")}>Reports</button>
      </div>

      {tab === "menu" && <MenuTab />}
      {tab === "inventory" && <InventoryTab />}
      {tab === "orders" && <OrdersTab />}
      {tab === "reports" && <ReportsTab />}
    </section>
  );
}
